/* eslint-disable */
// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  spring,
  Sequence,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');

// Load Google Font at module level to guarantee render-blocking until ready
const { fontFamily: spaceGroteskFamily } = loadSpaceGrotesk();



export type EffortAnimationProps = Record<string, any>;

const EffortAnimation: React.FC<EffortAnimationProps> = ({
  backgroundColor = "#050505",
  transparentBackground = false,
  durationInSeconds = 10,
  accentColor = "#FFD400",
  crowdColor = "rgba(255, 255, 255, 0.4)",
  textColor = "#FFFFFF",
  dotSize = 32,
  trailLength = 4,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout Constants
  const gridStartX = width * 0.5 - 240; // centered 5x3 grid (spacing 120px)
  const gridStartY = height * 0.65 - 120;
  const yStart1X = gridStartX + 240; // exact center column
  const yStart1Y = gridStartY + 120; // exact center row

  const stairsStartX = width * 0.2;
  const stairsStartY = height * 0.65;
  const stepW = (width * 0.6) / 4;
  const stepH = (height * 0.3) / 4;

  const goalX = width * 0.5;
  const goalY = height * 0.25;

  // Pre-calculate Crowd Positions (Deterministic)
  const crowd = React.useMemo(() => {
    const dots = [];
    for (let i = 0; i < 15; i++) {
      if (i === 7) continue; // Skip center dot (reserved for the yellow hero)
      dots.push({
        id: i,
        x: gridStartX + (i % 5) * 120,
        y: gridStartY + Math.floor(i / 5) * 120,
      });
    }
    return dots;
  }, [gridStartX, gridStartY]);

  // Pre-calculate Jump Frames for Stairs
  const { jumpFrames, xVals, yVals } = React.useMemo(() => {
    const jf = [100];
    const xv = [stairsStartX];
    const yv = [stairsStartY];

    for (let i = 0; i < 4; i++) {
      jf.push(jf[jf.length - 1] + 15);
      xv.push(xv[xv.length - 1] + stepW);
      yv.push(yv[yv.length - 1]);

      jf.push(jf[jf.length - 1] + 10);
      xv.push(xv[xv.length - 1]);
      yv.push(yv[yv.length - 1] - stepH);
    }
    return { jumpFrames: jf, xVals: xv, yVals: yv };
  }, [stairsStartX, stairsStartY, stepW, stepH]);

  // Main Logic for the Hero Yellow Dot's properties at any given frame
  const getHeroState = (f: number) => {
    let x = yStart1X;
    let y = yStart1Y;
    let s = 1;
    let o = 1;

    if (f < 0) return { x, y, s, o };

    if (f < 100) {
      // Scene 1: Drift with crowd, then break away and arc to stairs
      const crowdDrift = interpolate(f, [0, 90], [0, 200], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
      x = interpolate(f, [0, 30, 80], [yStart1X + crowdDrift, yStart1X + crowdDrift, stairsStartX], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
      y = interpolate(f, [0, 30, 60, 80], [yStart1Y, yStart1Y, yStart1Y - 150, stairsStartY], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
    } else if (f < 200) {
      // Scene 2: Climbing Stairs with bounces
      x = interpolate(f, jumpFrames, xVals, { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
      let bY = 0;
      for (let i = 0; i < 4; i++) {
        const startRight = 100 + i * 25;
        if (f >= startRight && f <= startRight + 15) {
          const p = (f - startRight) / 15;
          bY = Math.sin(p * Math.PI) * -40; // Parabolic bounce
        }
      }
      y = interpolate(f, jumpFrames, yVals, { extrapolateLeft: "clamp", extrapolateRight: "clamp" }) + bY;
    } else {
      // Scene 3: Final Leap to Goal
      x = interpolate(f, [200, 230], [xVals[8], goalX], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
      y = interpolate(f, [200, 215, 230], [yVals[8], yVals[8] - 150, goalY], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
      s = interpolate(f, [230, 240], [1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
      o = interpolate(f, [230, 240], [1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
    }
    return { x, y, s, o };
  };

  const hero = getHeroState(frame);

  // General Opacities
  const crowdOpacity = interpolate(frame, [60, 80], [1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const stairsOpacity = interpolate(frame, [80, 100, 200, 210], [0, 1, 1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  // Stairs Path Generation
  const stairsPath = React.useMemo(() => {
    let p = `M ${stairsStartX},${stairsStartY}`;
    for (let i = 1; i <= 4; i++) {
      p += ` L ${stairsStartX + i * stepW},${stairsStartY - (i - 1) * stepH}`;
      p += ` L ${stairsStartX + i * stepW},${stairsStartY - i * stepH}`;
    }
    return p;
  }, [stairsStartX, stairsStartY, stepH, stepW]);

  const stairsPathLength = 4 * (stepW + stepH);
  const stairsDrawOffset = interpolate(frame, [70, 100], [stairsPathLength, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  // Star / Goal properties
  const starScale = spring({ frame: frame - 230, fps, config: { stiffness: 120, damping: 12 } });
  const starRotate = interpolate(frame, [230, 300], [0, 90], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const pulseScale = spring({ frame: frame - 230, fps, config: { damping: 20 } }) * 2.5;
  const pulseOpacity = interpolate(frame, [230, 270], [0.6, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  // Text Animation Logic
  const t1O = interpolate(frame, [10, 20, 80, 90], [0, 1, 1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const t1Y = interpolate(frame, [10, 20], [30, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  const t2O = interpolate(frame, [90, 100, 160, 170], [0, 1, 1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const t2Y = interpolate(frame, [90, 100], [30, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  const t3O = interpolate(frame, [170, 180, 230, 240], [0, 1, 1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const t3Y = interpolate(frame, [170, 180], [30, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  const finalO = interpolate(frame, [240, 250], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const finalScale = spring({ frame: frame - 240, fps, config: { damping: 14 } });

  const commonTextStyle: React.CSSProperties = {
    position: "absolute",
    bottom: "12%",
    left: "10%",
    width: "80%",
    textAlign: "center",
    fontFamily: spaceGroteskFamily,
    fontSize: "55px",
    color: textColor,
    lineHeight: 1.4,
    fontWeight: 600,
    transition: "none",
  };

  const highlightStyle = {
    color: accentColor,
    fontWeight: 900,
    transition: "none",
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, transition: "none" }}>
      
      {/* 1. CROWD (Background Dots) */}
      {crowdOpacity > 0 && crowd.map((c) => {
        const drift = interpolate(frame, [0, 90], [0, 200], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
        return (
          <div
            key={`crowd-${c.id}`}
            style={{
              position: "absolute",
              left: c.x + drift,
              top: c.y,
              width: dotSize,
              height: dotSize,
              borderRadius: "50%",
              border: `4px solid ${crowdColor}`,
              backgroundColor: "transparent",
              opacity: crowdOpacity,
              transform: "translate(-50%, -50%)",
              transition: "none",
            }}
          />
        );
      })}

      {/* 2. STAIRS */}
      {stairsOpacity > 0 && (
        <svg
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            overflow: "visible",
            opacity: stairsOpacity,
            transition: "none",
          }}
        >
          <path
            d={stairsPath}
            fill="none"
            stroke={crowdColor}
            strokeWidth={4}
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeDasharray={stairsPathLength}
            strokeDashoffset={stairsDrawOffset}
            style={{ transition: "none" }}
          />
        </svg>
      )}

      {/* 3. HERO TRAIL */}
      {hero.o > 0 &&
        Array.from({ length: trailLength }).map((_, i) => {
          const delay = (i + 1) * 2;
          const trailHero = getHeroState(frame - delay);
          if (trailHero.o <= 0) return null;
          return (
            <div
              key={`trail-${i}`}
              style={{
                position: "absolute",
                left: trailHero.x,
                top: trailHero.y,
                width: dotSize * trailHero.s * (1 - (i * 0.15)),
                height: dotSize * trailHero.s * (1 - (i * 0.15)),
                borderRadius: "50%",
                backgroundColor: accentColor,
                opacity: trailHero.o * (0.4 - i * 0.1),
                transform: "translate(-50%, -50%)",
                filter: "blur(6px)",
                transition: "none",
              }}
            />
          );
        })}

      {/* 4. HERO DOT */}
      {hero.o > 0 && (
        <div
          style={{
            position: "absolute",
            left: hero.x,
            top: hero.y,
            width: dotSize * hero.s,
            height: dotSize * hero.s,
            borderRadius: "50%",
            backgroundColor: accentColor,
            opacity: hero.o,
            transform: "translate(-50%, -50%)",
            boxShadow: `0 0 20px ${accentColor}80`,
            transition: "none",
          }}
        />
      )}

      {/* 5. STAR GOAL (Final Scene) */}
      {frame >= 230 && (
        <AbsoluteFill style={{ transition: "none" }}>
          {/* Pulse Ring */}
          <div
            style={{
              position: "absolute",
              left: goalX,
              top: goalY,
              width: 120 * pulseScale,
              height: 120 * pulseScale,
              borderRadius: "50%",
              border: `4px solid ${accentColor}`,
              opacity: pulseOpacity,
              transform: "translate(-50%, -50%)",
              transition: "none",
            }}
          />
          {/* Star Icon */}
          <svg
            width={120}
            height={120}
            viewBox="0 0 24 24"
            style={{
              position: "absolute",
              left: goalX,
              top: goalY,
              transform: `translate(-50%, -50%) scale(${starScale}) rotate(${starRotate}deg)`,
              transition: "none",
            }}
          >
            {/* Elegant 4-point Spark Star */}
            <path
              fill={accentColor}
              d="M 12 0 C 12 8 20 12 24 12 C 20 12 12 16 12 24 C 12 16 4 12 0 12 C 4 12 12 8 12 0 Z"
            />
          </svg>
        </AbsoluteFill>
      )}

      {/* 6. TYPOGRAPHY */}
      <div
        style={{
          ...commonTextStyle,
          opacity: t1O,
          transform: `translateY(${t1Y}px)`,
        }}
      >
        The kind of <span style={highlightStyle}>EFFORT</span>
      </div>

      <div
        style={{
          ...commonTextStyle,
          opacity: t2O,
          transform: `translateY(${t2Y}px)`,
        }}
      >
        that you're <span style={highlightStyle}>WILLING</span> to do things
      </div>

      <div
        style={{
          ...commonTextStyle,
          opacity: t3O,
          transform: `translateY(${t3Y}px)`,
        }}
      >
        that many people are <br />
        <span style={highlightStyle}>UNWILLING</span> to do.
      </div>

      <div
        style={{
          ...commonTextStyle,
          top: "45%",
          bottom: "auto",
          opacity: finalO,
          transform: `scale(${finalScale})`,
          fontSize: "70px",
          fontWeight: 900,
          textTransform: "uppercase",
          letterSpacing: "2px",
        }}
      >
        Do what
        <br />
        <span style={highlightStyle}>others won't.</span>
      </div>
    </AbsoluteFill>
  );
};

export default EffortAnimation;